void TetRPOperatorTable::ApplyRestrict(int p_hi,
                                        const double* u_hi, int n_sp_hi,
                                        double* u_lo, int& n_sp_lo,
                                        int nv) const {
    if (p_hi < 1 || p_hi > max_order_) {
        throw std::runtime_error("TetRPOperatorTable::ApplyRestrict: invalid p_hi=" +
                                 std::to_string(p_hi));
    }
    const DenseMatrix& R = restrict_full_[p_hi];
    n_sp_lo = R.rows;
    
    // R * u: for each cell, R is [n_sp_lo x n_sp_hi]
    // Data layout: u[sp * nv + var] (interleaved)
    for (int v = 0; v < nv; ++v) {
        for (int i = 0; i < n_sp_lo; ++i) {
            double sum = 0.0;
            for (int j = 0; j < n_sp_hi; ++j) {
                sum += R(i, j) * u_hi[j * nv + v];
            }
            u_lo[i * nv + v] = sum;
        }
    }
}

void TetRPOperatorTable::ApplyProlong(int p_lo,
                                       const double* u_lo, int n_sp_lo,
                                       double* u_hi, int& n_sp_hi,
                                       int nv) const {
    if (p_lo < 0 || p_lo >= max_order_) {
        throw std::runtime_error("TetRPOperatorTable::ApplyProlong: invalid p_lo=" +
                                 std::to_string(p_lo));
    }
    const DenseMatrix& P = prolong_full_[p_lo];
    n_sp_hi = P.rows;
    
    // P * u: P is [n_sp_hi x n_sp_lo]
    // Data layout: u[sp * nv + var] (interleaved)
    for (int v = 0; v < nv; ++v) {
        for (int i = 0; i < n_sp_hi; ++i) {
            double sum = 0.0;
            for (int j = 0; j < n_sp_lo; ++j) {
                sum += P(i, j) * u_lo[j * nv + v];
            }
            u_hi[i * nv + v] = sum;
        }
    }
}

double TetRPOperatorTable::VerifyRP() const {
    double max_err = 0.0;
    for (int p = 1; p <= max_order_; ++p) {
        double e = VerifyRP(p);
        max_err = std::max(max_err, e);
    }
    return max_err;
}

double TetRPOperatorTable::VerifyRP(int p) const {
    const DenseMatrix& R = restrict_full_[p];
    const DenseMatrix& P = prolong_full_[p - 1];
    
    // R maps p -> p-1: [n_sp(p-1) x n_sp(p)]
    // P maps p-1 -> p: [n_sp(p) x n_sp(p-1)]
    // R * P should be identity [n_sp(p-1) x n_sp(p-1)]
    int n_lo = R.rows;   // n_sp(p-1)
    int n_hi = R.cols;   // n_sp(p)
    
    double max_err = 0.0;
    for (int i = 0; i < n_lo; ++i) {
        for (int j = 0; j < n_lo; ++j) {
            double sum = 0.0;
            for (int k = 0; k < n_hi; ++k) {
                sum += R(i, k) * P(k, j);
            }
            double expected = (i == j) ? 1.0 : 0.0;
            max_err = std::max(max_err, std::abs(sum - expected));
        }
    }
    return max_err;
}

void TetRPOperatorTable::PrintSummary() const {
    std::cout << "[TetRPOperatorTable] max_order=" << max_order_ << "\n";
    for (int p = 1; p <= max_order_; ++p) {
        const auto& R = restrict_full_[p];
        const auto& P = prolong_full_[p - 1];
        double rp_err = VerifyRP(p);
        std::cout << "  p=" << p << ": R[" << R.rows << "x" << R.cols
                  << "] P[" << P.rows << "x" << P.cols
                  << "] |R*P-I|=" << std::scientific << rp_err << "\n";
    }
}

